    /**
     * Method to retrieve the QualityCheck via QualityCheckFetchOneSummary
     * @param 	summary QualityCheckFetchOneSummary 
     * @return 	QualityCheckFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public QualityCheck getQualityCheck( QualityCheckFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "QualityCheckFetchOneSummary arg cannot be null" );
    	
    	QualityCheck entity = null;
    	UUID id = summary.getQualityCheckId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	QualityCheckValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a QualityCheck using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate QualityCheck with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


