    /**
     * assign Rule on QualityCheck
     * @param		command AssignRuleToQualityCheckCommand	
     * @exception	ProcessingException
     */     
	public void assignRule( AssignRuleToQualityCheckCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	QualityCheckValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignRule(command.getQualityCheckId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get QualityRule using id " + command.getQualityCheckId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

